from lib import *
S = SS('j270')
steps = [
    step("篡改(1 MiB 明文,JDK 21):未篡改的 GCM 密文(1048592 字节,多了 16 字节标签)读到 1048576 字节、正常到达 EOF。密文里翻转 1 位——倒数第 100 个字节、第 10 个字节、标签最后 1 位——三种情况都是“读到 0 字节后抛出 IOException ← AEADBadTagException: Tag mismatch”:一个明文字节都没有交给调用者,第一次 read() 就抛出。对比 CBC(PKCS5Padding,无认证):密文倒数第 100 个字节翻转 1 位,1048576 字节全部读出、正常到达 EOF——篡改完全没被发现;只有最后一个密文块被改时才碰运气得到 BadPaddingException。", t=tl(S(1)), done=lidx(S(1), 'GCM 未篡改', 'GCM 密文倒数第 100 个字节', 'GCM 密文第 10 个字节'), mark=lidx(S(1), 'GCM 标签的最后 1 位', 'CBC(PKCS5Padding,无认证)', 'CBC 最后一个密文块', 'GCM 被篡改的流第一次 read()'), kv=KV([['GCM 被篡改', '0 字节明文交出,第一次 read() 就抛 IOException(AEADBadTagException)'], ['CBC 被篡改(中间)', '1048576 字节正常读出,篡改未被发现']], ['CBC 被篡改(中间)'])),
    step("截断:GCM 密文去掉最后 16 字节、去掉最后 1 字节、只留后 1000 字节,都是读到 0 字节后抛 AEADBadTagException: Tag mismatch;只剩 10 字节或空密文抛 “Input data too short to contain an expected tag length of 16bytes”——截断一定被发现。CBC:完整密文读到 1048576 字节;在块边界截掉最后 1 个块(16 字节)PKCS5Padding 读到 1048560 字节后抛 BadPaddingException(碰巧);CBC/NoPadding 在块边界截掉最后 1 个块读到 1048560 字节、正常到达 EOF——没有任何错误,明文悄悄少了 16 字节;不在块边界截掉 5 字节抛 IllegalBlockSizeException。", t=tl(S(2)), done=lidx(S(2), 'GCM 密文去掉最后 16 字节', 'GCM 密文去掉最后 1 字节', '只留后 1000 字节'), mark=lidx(S(2), '只剩 10 字节', 'GCM 空密文', 'CBC 密文(PKCS5Padding)完整', 'CBC/NoPadding', '截掉最后 5 字节'), kv=KV([['GCM 截断', '一律抛 AEADBadTagException'], ['CBC/NoPadding 在块边界截断', '无错误,明文少 16 字节']], ['CBC/NoPadding 在块边界截断'])),
    step("close() 不验证:被篡改的 GCM 流没有读取就 close(),没有异常;未篡改的流读了 100 字节就 close(),没有异常;被篡改的流读 100 字节抛 Tag mismatch,之后再 close() 也没有异常。markSupported() = false,available() 读取前 = 0,skip(1000) = 0。CipherOutputStream(GCM)写 1000 字节后 flush() 但没有 close(),文件只有 992 字节(62 个完整的 16 字节分组),剩下的 8 字节密文和 16 字节标签要等 close() 才写出(close() 之后 1016 字节);不 close 的文件用 CipherInputStream 解密:读到 0 字节后抛 Tag mismatch。忘记 close 的加密文件解不开。", t=tl(S(3)), done=lidx(S(3), '被篡改的 GCM 流没有读取就 close()', '未篡改的 GCM 流读了 100 字节就 close()', '该流再 close()'), mark=lidx(S(3), 'markSupported()', 'flush() 但没有 close()', 'close() 之后文件 1016 字节', '既不 flush 也不 close', '不 close 的文件'), kv=KV([['close()', '不会触发验证,篡改的流也不抛'], ['CipherOutputStream 不 close', '文件 992 字节,缺尾部与标签,解密失败']], ['CipherOutputStream 不 close'])),
    step("内存(-Xmx128m,GCM 与 CBC 各加密后用 CipherInputStream 解密):10、20、30 MiB 两种都成功(GCM 解密 10 MiB 130 ms、30 MiB 367 ms;CBC 10 MiB 32 ms、30 MiB 55 ms);40、50、100、200 MiB:GCM 解密都是 OutOfMemoryError: Java heap space(加密本身都成功),CBC 全部成功(200 MiB 231 ms)。GCM 解密要在验证标签之前缓冲整个密文,所以不能用来流式解密大文件;大文件应该分块各自加密认证(每块一个 GCM 标签)。", t=tl(S(4)), done=lidx(S(4), 'GCM 用 CipherInputStream 解密 10 MiB', 'GCM 用 CipherInputStream 解密 30 MiB'), mark=lidx(S(4), 'GCM 处理 40 MiB', 'GCM 处理 200 MiB', 'CBC 用 CipherInputStream 解密 200 MiB'), b=bars([['GCM 能解密的最大(-Xmx128m)', 30, '30 MiB'], ['GCM 40 MiB', 40, 'OOM'], ['CBC 200 MiB', 200, '成功']], 200, done=[0, 1, 2]), kv=KV([['GCM(-Xmx128m)', '30 MiB 成功,40 MiB 起 OutOfMemoryError'], ['CBC(-Xmx128m)', '200 MiB 成功']], ['GCM(-Xmx128m)'])),
]
A = mkartj('j270', 270, 'Java,密码学,CipherInputStream,AES-GCM,认证加密,真实验证,动画演示',
    '在 JDK 21 上实测 CipherInputStream:GCM 被篡改或截断时一个明文字节都不交出并抛 IOException ← AEADBadTagException;CBC 无认证,中间篡改完全不被发现,NoPadding 在块边界截断悄悄少 16 字节;close() 不做验证;CipherOutputStream 忘记 close 得到 992 / 1016 字节的残缺文件;-Xmx128m 下 GCM 解密 40 MiB 起 OutOfMemoryError。',
    'CipherInputStream 看上去只是“解密版的 InputStream”,但认证加密的边界、截断与内存行为全不一样。这篇用真实的篡改、截断、关闭和大文件实验量出它的保证和限制。',
    [('0 字节', 'GCM 密文被篡改(任何位置)时,CipherInputStream 在异常前交给调用者的明文字节数'), ('1048576 字节', 'CBC 密文被篡改(中间)时读出的明文字节数——篡改没有被发现'), ('30 → 40 MiB', '-Xmx128m 下 GCM 用 CipherInputStream 解密成功与 OutOfMemoryError 的分界(CBC 200 MiB 仍成功)')],
    [('篡改', None), ('截断', None), ('close 与 flush', None), ('内存', None)],
    steps, [ENV_J + '。JDK 21.0.12(SunJCE);AES-128,全零密钥与随机明文(只用于实验);GCM 标签 128 位、IV 12 字节固定(只用于实验,真实使用必须每次不同)', '没有验证:JDK 17 / 27 的行为差异(JDK 对 GCM 解密的缓冲策略各版本不同)、Cipher.update 的逐块用法、ChaCha20-Poly1305 的流式行为、BouncyCastle 的 CipherInputStream、分块加密(STREAM / 每块一个标签)的实现与性能'], 'CipherInputStream')
